// src/group-pin.ts
function toggleGroupChatPinned(name) {
  const room = $groupChats.get()[name];
  if (!room || room.tombstone) {
    return null;
  }
  const pinned = !room.pinned;
  updateGroupChat(name, (current) => ({ ...current, pinned }), { sync: false });
  return pinned;
}

